Ext._define('judicial.council.ConvocationNoticeGrid', {
    extend: 'core.RestfulGrid',

    restWindow: 'judicial.council.ConvocationNoticeWindow',

    configOrderToolBar: ['add', 'edit', 'remove', '-', 'requestPublication', '-', '->', 'download'],

    _doRequestPublication: function(pkset) {
        var rest = this.factoryRestful();
        var mask = new Ext.LoadMask((this.ownerCt || this).getEl(), {msg: 'Requisitando publicação...'});

        mask.show();
        rest.doRequest(
            rest.getRoute(
                'request_publication',
                false,
                'POST',
                {
                    params: {
                        pkset: pkset
                    },
                    scope: this,
                    callback: function() {
                        mask.hide();
                    },
                    success: function(xhr) {
                        var rst = Ext.decode(xhr.responseText);

                        if(rst.success)
                            this.getStore().reload();
                        else
                            Ext.Msg.show({
                                title: 'Requisitando publicação',
                                icon: Ext.Msg.ERROR,
                                buttons: Ext.Msg.OK,
                                msg: rst.message
                            });
                    },
                    failure: function() {
                        Ext.Msg.show({
                            title: 'Requisitando publicação',
                            icon: Ext.Msg.ERROR,
                            buttons: Ext.Msg.OK,
                            msg: 'Este recurso esta indisponível no momento.'
                        });
                    },
                }
            )
        );
    },

    requestPublication: function() {
        var selected = this.getSelectionModel().getSelections();

        if(selected.length > 0) {
            Ext.Msg.show({
                title: 'Requisitando publicação',
                icon: Ext.Msg.QUESTION,
                buttons: Ext.Msg.YESNO,
                msg: 'Tem certeza que deseja solicitar a publicação dos itens selecionados?',
                scope: this,
                fn: function(btn) {
                    if(btn === 'yes')
                        this._doRequestPublication(
                            selected.map(function(data) {
                                return data.get('pk');
                            })
                        );
                }
            });
        }
        else
            Ext.Msg.show({
                title: 'Requisitando publicação',
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK,
                msg: 'Primeiro os editais que deseja fazer publicação.'
            });
    },

    getRequestPublicationAction: function(cfg) {
        if(!this._requestPublicationAction)
            this._requestPublicationAction = Ext._create('Ext.Button', {
                text: 'Pedir publicação',
                iconCls: 'icon-council icon-judicial-document-publishing',
                scope: this,
                handler: this.requestPublication
            });

        return this._requestPublicationAction;
    },

    countDownRenderer: function(value) {
        if(!value)
            return 'Indefinido';
        else if(value < 0)
            return 'Vencido';
        else if(value === 0)
            return 'Ultimo dia';
        else if(value === 1)
            return '1 dia';
        else if(value > 1)
            return value + ' dias';
    },

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: '', dataIndex: 'icons', width: 50, renderer: core.rendererIconGrid},
                    {header: 'Identificador', dataIndex: 'cached_number', id: 'autoExpandColumn'},
                    {header: 'Publicação', dataIndex: 'publication_unicode', width: 375},
                    {header: 'Data', dataIndex: 'publication_date', width: 115, renderer: Ext.util.Format.dateRenderer('d/m/Y')},
                    {header: 'Prazo', dataIndex: 'deadline_days', width: 70, renderer: this.countDownRenderer},
                ]
            );

        return this._columnModel;
    }
});

core.RestfulGrid.register(
    'judicial.council.ConvocationNoticeRestful',
    'judicial.council.ConvocationNoticeGrid'
);
